export const questions: Question[] = [
  { id: "y2df1-001", topicRef: "y2df1", topicTitle: "Differentiating 01", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = 3\\sin x - 2\\cos x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["differentiation", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the two standard derivatives.", workingLatex: "\\tfrac{d}{dx}\\sin x = \\cos x,\\;\\; \\tfrac{d}{dx}\\cos x = -\\sin x", explanation: "These are the building blocks for any linear combination of \\(\\sin x\\) and \\(\\cos x\\). The minus sign on the derivative of \\(\\cos x\\) is the single most common slip." }, { stepNumber: 2, description: "Apply linearity to split the derivative.", workingLatex: "\\tfrac{dy}{dx} = 3\\,\\tfrac{d}{dx}(\\sin x) - 2\\,\\tfrac{d}{dx}(\\cos x)", explanation: "Constants pull straight through differentiation, so each term can be handled separately." }, { stepNumber: 3, description: "Substitute the standard derivatives.", workingLatex: "\\tfrac{dy}{dx} = 3(\\cos x) - 2(-\\sin x)", explanation: "Bracket the \\(-\\sin x\\) carefully so the double negative is visible before simplifying." }, { stepNumber: 4, description: "Simplify the signs.", workingLatex: "\\tfrac{dy}{dx} = 3\\cos x + 2\\sin x", explanation: "The \\(-2 \\times -\\sin x\\) becomes \\(+2\\sin x\\). This sign-flip is exactly where most marks are lost." } ], finalAnswer: "\\( \\dfrac{dy}{dx} = 3\\cos x + 2\\sin x \\)" } },
  // ── Straight sin/cos ────
  { id: "y2df1-002", topicRef: "y2df1", topicTitle: "Differentiating 02", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = \\sin x \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the function to differentiate.", workingLatex: "y = \\sin x", explanation: "A bare \\(\\sin x\\) with no coefficient or inner function — the cleanest possible case." }, { stepNumber: 2, description: "Quote the standard derivative.", workingLatex: "\\tfrac{d}{dx}\\sin x = \\cos x", explanation: "This is one of the two standard trig derivatives that should be memorised. It holds only when \\(x\\) is measured in radians." }, { stepNumber: 3, description: "Write down the answer.", workingLatex: "\\tfrac{dy}{dx} = \\cos x", explanation: "Nothing further to simplify — the derivative of \\(\\sin x\\) is simply \\(\\cos x\\)." } ], finalAnswer: "\\( \\cos x \\)" } },
  { id: "y2df1-003", topicRef: "y2df1", topicTitle: "Differentiating 03", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = \\cos x \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the function.", workingLatex: "y = \\cos x", explanation: "A plain cosine, no coefficient and no inner function." }, { stepNumber: 2, description: "Quote the standard derivative.", workingLatex: "\\tfrac{d}{dx}\\cos x = -\\sin x", explanation: "The minus sign is essential and easy to forget. Like the \\(\\sin\\) result, this assumes \\(x\\) is in radians." }, { stepNumber: 3, description: "Write down the answer.", workingLatex: "\\tfrac{dy}{dx} = -\\sin x", explanation: "Direct application — the derivative of \\(\\cos x\\) is \\(-\\sin x\\)." } ], finalAnswer: "\\( -\\sin x \\)" } },
  { id: "y2df1-004", topicRef: "y2df1", topicTitle: "Differentiating 04", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = 5\\sin x \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the standard derivative.", workingLatex: "\\tfrac{d}{dx}\\sin x = \\cos x", explanation: "The building block needed for any constant multiple of \\(\\sin x\\)." }, { stepNumber: 2, description: "Pull the constant through.", workingLatex: "\\tfrac{dy}{dx} = 5\\,\\tfrac{d}{dx}(\\sin x)", explanation: "By linearity, constant multipliers stay outside the derivative." }, { stepNumber: 3, description: "Substitute the derivative.", workingLatex: "\\tfrac{dy}{dx} = 5\\cos x", explanation: "Replace \\(\\sin x\\) with its derivative \\(\\cos x\\) and the constant stays attached." } ], finalAnswer: "\\( 5\\cos x \\)" } },
  { id: "y2df1-005", topicRef: "y2df1", topicTitle: "Differentiating 05", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = 7\\cos x \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the standard derivative.", workingLatex: "\\tfrac{d}{dx}\\cos x = -\\sin x", explanation: "Note the leading minus — this is the trap of cosine differentiation." }, { stepNumber: 2, description: "Pull the constant through.", workingLatex: "\\tfrac{dy}{dx} = 7\\,\\tfrac{d}{dx}(\\cos x)", explanation: "Linearity lets the \\(7\\) sit outside while we differentiate the \\(\\cos x\\)." }, { stepNumber: 3, description: "Substitute and simplify.", workingLatex: "\\tfrac{dy}{dx} = 7(-\\sin x) = -7\\sin x", explanation: "Don't lose the minus sign that comes from \\(\\tfrac{d}{dx}\\cos x = -\\sin x\\)." } ], finalAnswer: "\\( -7\\sin x \\)" } },
  { id: "y2df1-006", topicRef: "y2df1", topicTitle: "Differentiating 06", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = -4\\sin x \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the standard derivative.", workingLatex: "\\tfrac{d}{dx}\\sin x = \\cos x", explanation: "Negative coefficients don't change the underlying rule." }, { stepNumber: 2, description: "Pull the constant through.", workingLatex: "\\tfrac{dy}{dx} = -4\\,\\tfrac{d}{dx}(\\sin x)", explanation: "Linearity: the \\(-4\\) factor commutes with differentiation." }, { stepNumber: 3, description: "Substitute.", workingLatex: "\\tfrac{dy}{dx} = -4\\cos x", explanation: "Substitute \\(\\cos x\\) for the derivative of \\(\\sin x\\) and keep the \\(-4\\) attached." } ], finalAnswer: "\\( -4\\cos x \\)" } },
  { id: "y2df1-007", topicRef: "y2df1", topicTitle: "Differentiating 07", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = -6\\cos x \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the standard derivative.", workingLatex: "\\tfrac{d}{dx}\\cos x = -\\sin x", explanation: "Cosine differentiates with an in-built minus sign." }, { stepNumber: 2, description: "Pull the constant through.", workingLatex: "\\tfrac{dy}{dx} = -6\\,\\tfrac{d}{dx}(\\cos x)", explanation: "Pull the \\(-6\\) outside; we now just need the derivative of \\(\\cos x\\)." }, { stepNumber: 3, description: "Substitute and simplify signs.", workingLatex: "\\tfrac{dy}{dx} = -6(-\\sin x) = 6\\sin x", explanation: "Two negatives multiply to a positive, so the final coefficient is \\(+6\\). A common slip is to leave the answer as \\(-6\\sin x\\)." } ], finalAnswer: "\\( 6\\sin x \\)" } },
  { id: "y2df1-008", topicRef: "y2df1", topicTitle: "Differentiating 08", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = \\sin x + \\cos x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the standard derivatives.", workingLatex: "\\tfrac{d}{dx}\\sin x = \\cos x,\\;\\; \\tfrac{d}{dx}\\cos x = -\\sin x", explanation: "Both standard results are needed in the same expression." }, { stepNumber: 2, description: "Apply linearity term by term.", workingLatex: "\\tfrac{dy}{dx} = \\tfrac{d}{dx}(\\sin x) + \\tfrac{d}{dx}(\\cos x)", explanation: "Sums differentiate term by term, so we just handle the two trig functions separately." }, { stepNumber: 3, description: "Substitute.", workingLatex: "\\tfrac{dy}{dx} = \\cos x + (-\\sin x)", explanation: "Use the two standard results, keeping brackets to track the sign." }, { stepNumber: 4, description: "Tidy the signs.", workingLatex: "\\tfrac{dy}{dx} = \\cos x - \\sin x", explanation: "The \\(\\sin x\\) term picks up a minus from the standard \\(\\cos x\\) derivative." } ], finalAnswer: "\\( \\cos x - \\sin x \\)" } },
  { id: "y2df1-009", topicRef: "y2df1", topicTitle: "Differentiating 09", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = \\sin x - \\cos x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the standard derivatives.", workingLatex: "\\tfrac{d}{dx}\\sin x = \\cos x,\\;\\; \\tfrac{d}{dx}\\cos x = -\\sin x", explanation: "Both rules are needed; the second has the trap-minus sign." }, { stepNumber: 2, description: "Differentiate each term.", workingLatex: "\\tfrac{dy}{dx} = \\tfrac{d}{dx}(\\sin x) - \\tfrac{d}{dx}(\\cos x)", explanation: "Linearity allows differentiating each term separately, keeping the subtraction." }, { stepNumber: 3, description: "Substitute.", workingLatex: "\\tfrac{dy}{dx} = \\cos x - (-\\sin x)", explanation: "Bracket the \\(-\\sin x\\) so the next sign flip is unambiguous." }, { stepNumber: 4, description: "Simplify the double negative.", workingLatex: "\\tfrac{dy}{dx} = \\cos x + \\sin x", explanation: "Subtracting \\(-\\sin x\\) is adding \\(\\sin x\\). Watch this sign — students often write \\(\\cos x - \\sin x\\) by reflex." } ], finalAnswer: "\\( \\cos x + \\sin x \\)" } },
  { id: "y2df1-010", topicRef: "y2df1", topicTitle: "Differentiating 10", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = 2\\sin x + 3\\cos x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply linearity.", workingLatex: "\\tfrac{dy}{dx} = 2\\,\\tfrac{d}{dx}(\\sin x) + 3\\,\\tfrac{d}{dx}(\\cos x)", explanation: "Constants pull through; each term differentiates independently." }, { stepNumber: 2, description: "Substitute the standard derivatives.", workingLatex: "\\tfrac{dy}{dx} = 2\\cos x + 3(-\\sin x)", explanation: "Use the two standard results carefully, holding onto the minus from \\(\\cos x\\)'s derivative." }, { stepNumber: 3, description: "Combine.", workingLatex: "\\tfrac{dy}{dx} = 2\\cos x - 3\\sin x", explanation: "Multiplying through gives the final form." } ], finalAnswer: "\\( 2\\cos x - 3\\sin x \\)" } },
  { id: "y2df1-011", topicRef: "y2df1", topicTitle: "Differentiating 11", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = 4\\sin x - 5\\cos x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply linearity.", workingLatex: "\\tfrac{dy}{dx} = 4\\,\\tfrac{d}{dx}(\\sin x) - 5\\,\\tfrac{d}{dx}(\\cos x)", explanation: "Differentiate term by term, keeping the constants attached." }, { stepNumber: 2, description: "Substitute the standard derivatives.", workingLatex: "\\tfrac{dy}{dx} = 4\\cos x - 5(-\\sin x)", explanation: "The \\(-5\\) is being multiplied by \\(-\\sin x\\), which will flip the sign." }, { stepNumber: 3, description: "Simplify the double negative.", workingLatex: "\\tfrac{dy}{dx} = 4\\cos x + 5\\sin x", explanation: "The \\(-5 \\times -\\sin x\\) becomes \\(+5\\sin x\\)." } ], finalAnswer: "\\( 4\\cos x + 5\\sin x \\)" } },
  { id: "y2df1-012", topicRef: "y2df1", topicTitle: "Differentiating 12", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = -2\\sin x + 7\\cos x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply linearity.", workingLatex: "\\tfrac{dy}{dx} = -2\\,\\tfrac{d}{dx}(\\sin x) + 7\\,\\tfrac{d}{dx}(\\cos x)", explanation: "Pull out the constants and handle each term." }, { stepNumber: 2, description: "Substitute the standard derivatives.", workingLatex: "\\tfrac{dy}{dx} = -2\\cos x + 7(-\\sin x)", explanation: "The \\(\\cos x\\) keeps its negative sign coefficient; the \\(\\sin x\\) picks up the minus from \\(\\tfrac{d}{dx}\\cos x\\)." }, { stepNumber: 3, description: "Tidy the signs.", workingLatex: "\\tfrac{dy}{dx} = -2\\cos x - 7\\sin x", explanation: "Both terms end up negative." } ], finalAnswer: "\\( -2\\cos x - 7\\sin x \\)" } },
  { id: "y2df1-013", topicRef: "y2df1", topicTitle: "Differentiating 13", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = 6\\sin x + 8\\cos x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply linearity.", workingLatex: "\\tfrac{dy}{dx} = 6\\,\\tfrac{d}{dx}(\\sin x) + 8\\,\\tfrac{d}{dx}(\\cos x)", explanation: "Constants pull through; differentiate term by term." }, { stepNumber: 2, description: "Substitute the standard derivatives.", workingLatex: "\\tfrac{dy}{dx} = 6\\cos x + 8(-\\sin x)", explanation: "Use \\(\\tfrac{d}{dx}\\sin x = \\cos x\\) and \\(\\tfrac{d}{dx}\\cos x = -\\sin x\\)." }, { stepNumber: 3, description: "Combine.", workingLatex: "\\tfrac{dy}{dx} = 6\\cos x - 8\\sin x", explanation: "The \\(+8 \\times -\\sin x\\) gives \\(-8\\sin x\\)." } ], finalAnswer: "\\( 6\\cos x - 8\\sin x \\)" } },
  { id: "y2df1-014", topicRef: "y2df1", topicTitle: "Differentiating 14", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = 10\\sin x \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the standard derivative.", workingLatex: "\\tfrac{d}{dx}\\sin x = \\cos x", explanation: "Any constant multiple of \\(\\sin x\\) reduces to this rule." }, { stepNumber: 2, description: "Pull the constant through.", workingLatex: "\\tfrac{dy}{dx} = 10\\,\\tfrac{d}{dx}(\\sin x)", explanation: "Linearity allows the \\(10\\) to stay outside the derivative operator." }, { stepNumber: 3, description: "Substitute.", workingLatex: "\\tfrac{dy}{dx} = 10\\cos x", explanation: "Replace \\(\\sin x\\) with \\(\\cos x\\); the constant survives unchanged." } ], finalAnswer: "\\( 10\\cos x \\)" } },
  { id: "y2df1-015", topicRef: "y2df1", topicTitle: "Differentiating 15", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = \\tfrac{1}{2}\\sin x + \\tfrac{1}{3}\\cos x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply linearity to fractional coefficients.", workingLatex: "\\tfrac{dy}{dx} = \\tfrac{1}{2}\\,\\tfrac{d}{dx}(\\sin x) + \\tfrac{1}{3}\\,\\tfrac{d}{dx}(\\cos x)", explanation: "Fractional constants behave just like whole-number constants under differentiation." }, { stepNumber: 2, description: "Substitute the standard derivatives.", workingLatex: "\\tfrac{dy}{dx} = \\tfrac{1}{2}\\cos x + \\tfrac{1}{3}(-\\sin x)", explanation: "The fractions are unaffected; only the trig functions change." }, { stepNumber: 3, description: "Tidy the signs.", workingLatex: "\\tfrac{dy}{dx} = \\tfrac{1}{2}\\cos x - \\tfrac{1}{3}\\sin x", explanation: "The minus from \\(\\tfrac{d}{dx}\\cos x\\) flips the \\(\\sin x\\) term negative." } ], finalAnswer: "\\( \\tfrac{1}{2}\\cos x - \\tfrac{1}{3}\\sin x \\)" } },
  // ── With added constants ────
  { id: "y2df1-016", topicRef: "y2df1", topicTitle: "Differentiating 16", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = \\sin x + 5 \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the relevant derivatives.", workingLatex: "\\tfrac{d}{dx}\\sin x = \\cos x,\\;\\; \\tfrac{d}{dx}(c) = 0", explanation: "Two rules: the standard trig derivative and the constant rule." }, { stepNumber: 2, description: "Differentiate term by term.", workingLatex: "\\tfrac{dy}{dx} = \\tfrac{d}{dx}(\\sin x) + \\tfrac{d}{dx}(5)", explanation: "Linearity lets us split the sum into separate derivatives." }, { stepNumber: 3, description: "Apply both rules.", workingLatex: "\\tfrac{dy}{dx} = \\cos x + 0", explanation: "The derivative of any constant is \\(0\\), so the \\(+5\\) just disappears." }, { stepNumber: 4, description: "State the result.", workingLatex: "\\tfrac{dy}{dx} = \\cos x", explanation: "Only the \\(\\sin x\\) term contributes." } ], finalAnswer: "\\( \\cos x \\)" } },
  { id: "y2df1-017", topicRef: "y2df1", topicTitle: "Differentiating 17", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = \\cos x - 7 \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the relevant derivatives.", workingLatex: "\\tfrac{d}{dx}\\cos x = -\\sin x,\\;\\; \\tfrac{d}{dx}(c) = 0", explanation: "Trig derivative plus the constant rule." }, { stepNumber: 2, description: "Differentiate term by term.", workingLatex: "\\tfrac{dy}{dx} = \\tfrac{d}{dx}(\\cos x) - \\tfrac{d}{dx}(7)", explanation: "Linearity splits the expression into separate derivatives." }, { stepNumber: 3, description: "Apply both rules.", workingLatex: "\\tfrac{dy}{dx} = -\\sin x - 0", explanation: "The derivative of \\(7\\) is \\(0\\); the \\(\\cos x\\) contributes \\(-\\sin x\\)." }, { stepNumber: 4, description: "Simplify.", workingLatex: "\\tfrac{dy}{dx} = -\\sin x", explanation: "Only the \\(\\cos x\\) contributes, carrying its minus sign." } ], finalAnswer: "\\( -\\sin x \\)" } },
  { id: "y2df1-018", topicRef: "y2df1", topicTitle: "Differentiating 18", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = 3\\sin x + 2x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply linearity to each term.", workingLatex: "\\tfrac{dy}{dx} = 3\\,\\tfrac{d}{dx}(\\sin x) + \\tfrac{d}{dx}(2x)", explanation: "The two terms differentiate independently." }, { stepNumber: 2, description: "Differentiate the trig term.", workingLatex: "\\tfrac{d}{dx}(3\\sin x) = 3\\cos x", explanation: "Standard result with the constant carried through." }, { stepNumber: 3, description: "Differentiate the polynomial term.", workingLatex: "\\tfrac{d}{dx}(2x) = 2", explanation: "Power rule on \\(x^1\\) gives the constant \\(2\\)." }, { stepNumber: 4, description: "Combine.", workingLatex: "\\tfrac{dy}{dx} = 3\\cos x + 2", explanation: "Add the two pieces to get the full derivative." } ], finalAnswer: "\\( 3\\cos x + 2 \\)" } },
  { id: "y2df1-019", topicRef: "y2df1", topicTitle: "Differentiating 19", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = 4\\cos x - x^2 \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply linearity to each term.", workingLatex: "\\tfrac{dy}{dx} = 4\\,\\tfrac{d}{dx}(\\cos x) - \\tfrac{d}{dx}(x^2)", explanation: "Trig and polynomial terms can be differentiated independently." }, { stepNumber: 2, description: "Differentiate the trig term.", workingLatex: "4\\,\\tfrac{d}{dx}(\\cos x) = 4(-\\sin x) = -4\\sin x", explanation: "Use \\(\\tfrac{d}{dx}\\cos x = -\\sin x\\), giving a negative leading coefficient." }, { stepNumber: 3, description: "Differentiate the polynomial term.", workingLatex: "\\tfrac{d}{dx}(x^2) = 2x", explanation: "Power rule: bring the \\(2\\) down and reduce the exponent by one." }, { stepNumber: 4, description: "Combine.", workingLatex: "\\tfrac{dy}{dx} = -4\\sin x - 2x", explanation: "Subtracting \\(2x\\) gives the final derivative." } ], finalAnswer: "\\( -4\\sin x - 2x \\)" } },
  { id: "y2df1-020", topicRef: "y2df1", topicTitle: "Differentiating 20", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = \\sin x + \\cos x + x^3 \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply linearity term by term.", workingLatex: "\\tfrac{dy}{dx} = \\tfrac{d}{dx}(\\sin x) + \\tfrac{d}{dx}(\\cos x) + \\tfrac{d}{dx}(x^3)", explanation: "All three terms separate under differentiation." }, { stepNumber: 2, description: "Differentiate the trig terms.", workingLatex: "\\tfrac{d}{dx}(\\sin x) + \\tfrac{d}{dx}(\\cos x) = \\cos x - \\sin x", explanation: "Standard results applied to each function." }, { stepNumber: 3, description: "Differentiate the polynomial term.", workingLatex: "\\tfrac{d}{dx}(x^3) = 3x^2", explanation: "Power rule on \\(x^3\\)." }, { stepNumber: 4, description: "Combine into the final answer.", workingLatex: "\\tfrac{dy}{dx} = \\cos x - \\sin x + 3x^2", explanation: "Putting the three pieces together gives the complete derivative." } ], finalAnswer: "\\( \\cos x - \\sin x + 3x^2 \\)" } },
  // ── Linear-argument chain (y = sin kx, cos kx) ────
  { id: "y2df1-021", topicRef: "y2df1", topicTitle: "Differentiating 21", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = \\sin 2x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "chain"], workedSolution: { steps: [ { stepNumber: 1, description: "Recognise the linear inner function.", workingLatex: "y = \\sin(2x),\\; \\text{inner } u = 2x", explanation: "The argument of sine is not just \\(x\\) — it's \\(2x\\). This needs the chain rule." }, { stepNumber: 2, description: "State the linear-argument rule.", workingLatex: "\\tfrac{d}{dx}\\sin(kx) = k\\cos(kx)", explanation: "When the argument is a constant multiple of \\(x\\), the chain rule produces an extra factor of \\(k\\) — the derivative of the inner function." }, { stepNumber: 3, description: "Identify \\(k\\).", workingLatex: "k = 2", explanation: "The coefficient of \\(x\\) inside the bracket." }, { stepNumber: 4, description: "Apply the rule.", workingLatex: "\\tfrac{dy}{dx} = 2\\cos 2x", explanation: "Replace \\(\\sin\\) by \\(\\cos\\) and multiply by \\(k = 2\\)." } ], finalAnswer: "\\( 2\\cos 2x \\)" } },
  { id: "y2df1-022", topicRef: "y2df1", topicTitle: "Differentiating 22", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = \\cos 3x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "chain"], workedSolution: { steps: [ { stepNumber: 1, description: "Recognise the linear inner function.", workingLatex: "y = \\cos(3x),\\; \\text{inner } u = 3x", explanation: "The argument is \\(3x\\), so the chain rule is needed." }, { stepNumber: 2, description: "State the linear-argument rule.", workingLatex: "\\tfrac{d}{dx}\\cos(kx) = -k\\sin(kx)", explanation: "Chain rule on a linear inner function multiplies by the inner derivative \\(k\\), and \\(\\cos\\) contributes the usual minus sign." }, { stepNumber: 3, description: "Identify \\(k\\).", workingLatex: "k = 3", explanation: "The argument \\(3x\\) means \\(k = 3\\)." }, { stepNumber: 4, description: "Apply the rule.", workingLatex: "\\tfrac{dy}{dx} = -3\\sin 3x", explanation: "Multiply by \\(k\\) and apply the minus sign from differentiating \\(\\cos\\)." } ], finalAnswer: "\\( -3\\sin 3x \\)" } },
  { id: "y2df1-023", topicRef: "y2df1", topicTitle: "Differentiating 23", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = \\sin 4x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-argument rule.", workingLatex: "\\tfrac{d}{dx}\\sin(kx) = k\\cos(kx)", explanation: "When the argument is \\(kx\\), the chain rule multiplies the standard derivative by the inner derivative \\(k\\)." }, { stepNumber: 2, description: "Identify \\(k\\).", workingLatex: "k = 4", explanation: "Read off the coefficient of \\(x\\) inside the bracket." }, { stepNumber: 3, description: "Apply the rule.", workingLatex: "\\tfrac{dy}{dx} = 4\\cos 4x", explanation: "Swap \\(\\sin\\) for \\(\\cos\\) and multiply by \\(4\\); the argument \\(4x\\) is unchanged." } ], finalAnswer: "\\( 4\\cos 4x \\)" } },
  { id: "y2df1-024", topicRef: "y2df1", topicTitle: "Differentiating 24", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = \\cos 5x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-argument rule.", workingLatex: "\\tfrac{d}{dx}\\cos(kx) = -k\\sin(kx)", explanation: "Differentiating \\(\\cos\\) gives \\(-\\sin\\), and the chain rule on the inner \\(kx\\) brings down an additional factor of \\(k\\)." }, { stepNumber: 2, description: "Identify \\(k\\).", workingLatex: "k = 5", explanation: "The coefficient of \\(x\\) inside the cosine." }, { stepNumber: 3, description: "Apply the rule.", workingLatex: "\\tfrac{dy}{dx} = -5\\sin 5x", explanation: "Multiply by \\(5\\) and attach the minus sign from \\(\\cos\\)'s derivative." } ], finalAnswer: "\\( -5\\sin 5x \\)" } },
  { id: "y2df1-025", topicRef: "y2df1", topicTitle: "Differentiating 25", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = 3\\sin 2x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-argument rule.", workingLatex: "\\tfrac{d}{dx}\\sin(kx) = k\\cos(kx)", explanation: "The base rule we'll combine with linearity." }, { stepNumber: 2, description: "Pull the constant through.", workingLatex: "\\tfrac{dy}{dx} = 3\\,\\tfrac{d}{dx}(\\sin 2x)", explanation: "The constant \\(3\\) doesn't interact with the chain rule — it stays as a multiplier." }, { stepNumber: 3, description: "Differentiate \\(\\sin 2x\\).", workingLatex: "\\tfrac{d}{dx}(\\sin 2x) = 2\\cos 2x", explanation: "The factor \\(2\\) comes from the inner derivative \\(\\tfrac{d}{dx}(2x)\\)." }, { stepNumber: 4, description: "Multiply through.", workingLatex: "\\tfrac{dy}{dx} = 3 \\cdot 2\\cos 2x = 6\\cos 2x", explanation: "Combine the outer constant and the chain-rule factor: \\(3 \\times 2 = 6\\)." } ], finalAnswer: "\\( 6\\cos 2x \\)" } },
  { id: "y2df1-026", topicRef: "y2df1", topicTitle: "Differentiating 26", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = 2\\cos 3x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-argument rule.", workingLatex: "\\tfrac{d}{dx}\\cos(kx) = -k\\sin(kx)", explanation: "The chain-rule extension for cosine, carrying its built-in minus." }, { stepNumber: 2, description: "Pull the constant through.", workingLatex: "\\tfrac{dy}{dx} = 2\\,\\tfrac{d}{dx}(\\cos 3x)", explanation: "The constant \\(2\\) sits outside while we deal with the cosine." }, { stepNumber: 3, description: "Apply the rule to \\(\\cos 3x\\).", workingLatex: "\\tfrac{d}{dx}(\\cos 3x) = -3\\sin 3x", explanation: "Differentiate \\(\\cos\\) (gives \\(-\\sin\\)) and multiply by the inner derivative \\(3\\)." }, { stepNumber: 4, description: "Multiply through.", workingLatex: "\\tfrac{dy}{dx} = 2(-3\\sin 3x) = -6\\sin 3x", explanation: "Combine the outer \\(2\\) with the chain-rule factor \\(-3\\)." } ], finalAnswer: "\\( -6\\sin 3x \\)" } },
  { id: "y2df1-027", topicRef: "y2df1", topicTitle: "Differentiating 27", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = 5\\sin 4x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-argument rule.", workingLatex: "\\tfrac{d}{dx}\\sin(kx) = k\\cos(kx)", explanation: "The rule we need." }, { stepNumber: 2, description: "Pull the constant through.", workingLatex: "\\tfrac{dy}{dx} = 5\\,\\tfrac{d}{dx}(\\sin 4x)", explanation: "The \\(5\\) is independent of \\(x\\), so it factors out of the derivative." }, { stepNumber: 3, description: "Apply the rule with \\(k = 4\\).", workingLatex: "\\tfrac{d}{dx}(\\sin 4x) = 4\\cos 4x", explanation: "Inner derivative \\(\\tfrac{d}{dx}(4x) = 4\\) multiplies the outer \\(\\cos\\)." }, { stepNumber: 4, description: "Combine the constants.", workingLatex: "\\tfrac{dy}{dx} = 5 \\cdot 4\\cos 4x = 20\\cos 4x", explanation: "Multiply \\(5 \\times 4 = 20\\)." } ], finalAnswer: "\\( 20\\cos 4x \\)" } },
  { id: "y2df1-028", topicRef: "y2df1", topicTitle: "Differentiating 28", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = -4\\cos 6x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-argument rule.", workingLatex: "\\tfrac{d}{dx}\\cos(kx) = -k\\sin(kx)", explanation: "The rule we need, with its built-in minus." }, { stepNumber: 2, description: "Pull the constant through.", workingLatex: "\\tfrac{dy}{dx} = -4\\,\\tfrac{d}{dx}(\\cos 6x)", explanation: "The \\(-4\\) is a constant multiplier and pulls outside the derivative." }, { stepNumber: 3, description: "Apply the rule with \\(k = 6\\).", workingLatex: "\\tfrac{d}{dx}(\\cos 6x) = -6\\sin 6x", explanation: "Inner derivative is \\(6\\); \\(\\cos\\) contributes the usual minus sign." }, { stepNumber: 4, description: "Multiply through.", workingLatex: "\\tfrac{dy}{dx} = -4(-6\\sin 6x) = 24\\sin 6x", explanation: "Two negatives multiply to a positive; \\(4 \\times 6 = 24\\)." } ], finalAnswer: "\\( 24\\sin 6x \\)" } },
  { id: "y2df1-029", topicRef: "y2df1", topicTitle: "Differentiating 29", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = \\sin(x/2) \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Rewrite the argument.", workingLatex: "\\sin(x/2) = \\sin(\\tfrac{1}{2}x)", explanation: "Make the linear coefficient explicit so the chain rule structure is unambiguous." }, { stepNumber: 2, description: "Identify \\(k\\).", workingLatex: "k = \\tfrac{1}{2}", explanation: "The coefficient of \\(x\\) inside the bracket — fractional but still a constant." }, { stepNumber: 3, description: "Apply the linear-argument rule.", workingLatex: "\\tfrac{dy}{dx} = k\\cos(kx) = \\tfrac{1}{2}\\cos(x/2)", explanation: "The chain rule contributes the fractional factor \\(\\tfrac{1}{2}\\) — easy to drop if the substitution isn't explicit." } ], finalAnswer: "\\( \\tfrac{1}{2}\\cos(x/2) \\)" } },
  { id: "y2df1-030", topicRef: "y2df1", topicTitle: "Differentiating 30", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = \\cos(x/3) \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Rewrite the argument.", workingLatex: "\\cos(x/3) = \\cos(\\tfrac{1}{3}x)", explanation: "Make the linear coefficient explicit." }, { stepNumber: 2, description: "Identify \\(k\\).", workingLatex: "k = \\tfrac{1}{3}", explanation: "The fractional coefficient of \\(x\\) inside the bracket." }, { stepNumber: 3, description: "Apply the linear-argument rule.", workingLatex: "\\tfrac{dy}{dx} = -k\\sin(kx) = -\\tfrac{1}{3}\\sin(x/3)", explanation: "\\(\\cos\\) contributes a minus and the inner derivative is \\(\\tfrac{1}{3}\\)." } ], finalAnswer: "\\( -\\tfrac{1}{3}\\sin(x/3) \\)" } },
  { id: "y2df1-031", topicRef: "y2df1", topicTitle: "Differentiating 31", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = \\sin(\\pi x) \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-argument rule.", workingLatex: "\\tfrac{d}{dx}\\sin(kx) = k\\cos(kx)", explanation: "Apply with whatever \\(k\\) appears inside, treating \\(\\pi\\) like any other constant." }, { stepNumber: 2, description: "Identify \\(k\\).", workingLatex: "k = \\pi", explanation: "\\(\\pi\\) is a constant, so it plays the same role as any other linear coefficient." }, { stepNumber: 3, description: "Apply the rule.", workingLatex: "\\tfrac{dy}{dx} = \\pi\\cos(\\pi x)", explanation: "The chain rule multiplies by the constant \\(\\pi\\); the cosine argument stays \\(\\pi x\\)." } ], finalAnswer: "\\( \\pi\\cos(\\pi x) \\)" } },
  { id: "y2df1-032", topicRef: "y2df1", topicTitle: "Differentiating 32", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = \\cos(2\\pi x) \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-argument rule.", workingLatex: "\\tfrac{d}{dx}\\cos(kx) = -k\\sin(kx)", explanation: "Standard chain-rule extension for cosine." }, { stepNumber: 2, description: "Identify \\(k\\).", workingLatex: "k = 2\\pi", explanation: "Read off the coefficient of \\(x\\); \\(2\\pi\\) is a single constant." }, { stepNumber: 3, description: "Apply the rule.", workingLatex: "\\tfrac{dy}{dx} = -2\\pi\\sin(2\\pi x)", explanation: "Differentiating \\(\\cos\\) gives \\(-\\sin\\); the chain rule attaches the factor \\(2\\pi\\)." } ], finalAnswer: "\\( -2\\pi\\sin(2\\pi x) \\)" } },
  { id: "y2df1-033", topicRef: "y2df1", topicTitle: "Differentiating 33", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = \\sin(-x) \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(k = -1\\).", workingLatex: "y = \\sin(-x),\\; k = -1", explanation: "Negative \\(k\\) values work in the same rule." }, { stepNumber: 2, description: "Apply the linear-argument rule.", workingLatex: "\\tfrac{dy}{dx} = k\\cos(kx) = -\\cos(-x)", explanation: "The chain-rule factor is \\(k = -1\\)." }, { stepNumber: 3, description: "Use the even-function property of \\(\\cos\\).", workingLatex: "\\cos(-x) = \\cos x", explanation: "Cosine is an even function, so the sign of the argument is irrelevant." }, { stepNumber: 4, description: "Simplify.", workingLatex: "\\tfrac{dy}{dx} = -\\cos x", explanation: "Equivalently, since \\(\\sin(-x) = -\\sin x\\), differentiating gives \\(-\\cos x\\)." } ], finalAnswer: "\\( -\\cos x \\)" } },
  { id: "y2df1-034", topicRef: "y2df1", topicTitle: "Differentiating 34", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = \\cos(-2x) \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify \\(k = -2\\).", workingLatex: "y = \\cos(-2x),\\; k = -2", explanation: "The chain rule handles negative inner derivatives the same way." }, { stepNumber: 2, description: "Apply the linear-argument rule.", workingLatex: "\\tfrac{dy}{dx} = -k\\sin(kx) = -(-2)\\sin(-2x) = 2\\sin(-2x)", explanation: "Multiply by \\(-k\\); here \\(-(-2) = +2\\)." }, { stepNumber: 3, description: "Use the odd-function property of \\(\\sin\\).", workingLatex: "\\sin(-2x) = -\\sin 2x", explanation: "Sine is odd, so flipping the sign inside flips the value outside." }, { stepNumber: 4, description: "Simplify.", workingLatex: "\\tfrac{dy}{dx} = 2(-\\sin 2x) = -2\\sin 2x", explanation: "Equivalently, since \\(\\cos(-2x) = \\cos 2x\\), differentiating gives \\(-2\\sin 2x\\) directly." } ], finalAnswer: "\\( -2\\sin 2x \\)" } },
  { id: "y2df1-035", topicRef: "y2df1", topicTitle: "Differentiating 35", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = 3\\sin 2x + 4\\cos 3x \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Split using linearity.", workingLatex: "\\tfrac{dy}{dx} = 3\\,\\tfrac{d}{dx}(\\sin 2x) + 4\\,\\tfrac{d}{dx}(\\cos 3x)", explanation: "Handle each linear-argument trig term separately." }, { stepNumber: 2, description: "Differentiate \\(\\sin 2x\\).", workingLatex: "3\\,\\tfrac{d}{dx}(\\sin 2x) = 3(2\\cos 2x) = 6\\cos 2x", explanation: "Inner derivative \\(2\\) multiplies the outer \\(\\cos\\) and the leading constant." }, { stepNumber: 3, description: "Differentiate \\(\\cos 3x\\).", workingLatex: "4\\,\\tfrac{d}{dx}(\\cos 3x) = 4(-3\\sin 3x) = -12\\sin 3x", explanation: "\\(\\cos\\) contributes \\(-\\sin\\), inner derivative \\(3\\), and the outer \\(4\\) combine." }, { stepNumber: 4, description: "Combine the two pieces.", workingLatex: "\\tfrac{dy}{dx} = 6\\cos 2x - 12\\sin 3x", explanation: "Add the two contributions." } ], finalAnswer: "\\( 6\\cos 2x - 12\\sin 3x \\)" } },
  { id: "y2df1-036", topicRef: "y2df1", topicTitle: "Differentiating 36", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = \\sin 2x - \\cos 4x \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate each term separately.", workingLatex: "\\tfrac{dy}{dx} = \\tfrac{d}{dx}(\\sin 2x) - \\tfrac{d}{dx}(\\cos 4x)", explanation: "Subtraction differentiates term by term, with the minus sign attached." }, { stepNumber: 2, description: "Differentiate \\(\\sin 2x\\).", workingLatex: "\\tfrac{d}{dx}(\\sin 2x) = 2\\cos 2x", explanation: "Linear-argument rule with \\(k = 2\\)." }, { stepNumber: 3, description: "Differentiate \\(\\cos 4x\\).", workingLatex: "\\tfrac{d}{dx}(\\cos 4x) = -4\\sin 4x", explanation: "Linear-argument rule with \\(k = 4\\), plus the minus from \\(\\cos\\)'s derivative." }, { stepNumber: 4, description: "Combine, carrying the outer minus.", workingLatex: "\\tfrac{dy}{dx} = 2\\cos 2x - (-4\\sin 4x) = 2\\cos 2x + 4\\sin 4x", explanation: "The outer subtraction flips the sign of the second term — watch this double negative." } ], finalAnswer: "\\( 2\\cos 2x + 4\\sin 4x \\)" } },
  { id: "y2df1-037", topicRef: "y2df1", topicTitle: "Differentiating 37", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = 2\\sin 5x - 3\\cos 2x \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply linearity.", workingLatex: "\\tfrac{dy}{dx} = 2\\,\\tfrac{d}{dx}(\\sin 5x) - 3\\,\\tfrac{d}{dx}(\\cos 2x)", explanation: "Constants pull through; handle each term independently." }, { stepNumber: 2, description: "Differentiate \\(\\sin 5x\\).", workingLatex: "2\\,\\tfrac{d}{dx}(\\sin 5x) = 2(5\\cos 5x) = 10\\cos 5x", explanation: "Inner derivative \\(5\\) multiplies the outer constant." }, { stepNumber: 3, description: "Differentiate \\(\\cos 2x\\).", workingLatex: "-3\\,\\tfrac{d}{dx}(\\cos 2x) = -3(-2\\sin 2x) = 6\\sin 2x", explanation: "Triple sign care: outer \\(-3\\), inner \\(-\\sin\\) from \\(\\cos\\)'s derivative, and inner derivative \\(2\\)." }, { stepNumber: 4, description: "Combine.", workingLatex: "\\tfrac{dy}{dx} = 10\\cos 5x + 6\\sin 2x", explanation: "The two contributions add to give the final form." } ], finalAnswer: "\\( 10\\cos 5x + 6\\sin 2x \\)" } },
  { id: "y2df1-038", topicRef: "y2df1", topicTitle: "Differentiating 38", difficulty: "Challenge", answerType: "expression", questionText: "Differentiate \\( y = 6\\sin(x/2) + 4\\cos(x/3) \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply linearity.", workingLatex: "\\tfrac{dy}{dx} = 6\\,\\tfrac{d}{dx}\\sin(x/2) + 4\\,\\tfrac{d}{dx}\\cos(x/3)", explanation: "Each term has a different linear coefficient inside, so we differentiate them separately." }, { stepNumber: 2, description: "Differentiate \\(\\sin(x/2)\\).", workingLatex: "\\tfrac{d}{dx}\\sin(x/2) = \\tfrac{1}{2}\\cos(x/2)", explanation: "Chain rule contributes the inner derivative \\(\\tfrac{1}{2}\\)." }, { stepNumber: 3, description: "Multiply by the outer constant \\(6\\).", workingLatex: "6 \\cdot \\tfrac{1}{2}\\cos(x/2) = 3\\cos(x/2)", explanation: "The factor of two cancels neatly." }, { stepNumber: 4, description: "Differentiate \\(\\cos(x/3)\\).", workingLatex: "\\tfrac{d}{dx}\\cos(x/3) = -\\tfrac{1}{3}\\sin(x/3)", explanation: "Chain rule on \\(\\cos\\) with inner derivative \\(\\tfrac{1}{3}\\)." }, { stepNumber: 5, description: "Multiply by the outer constant \\(4\\).", workingLatex: "4 \\cdot \\left(-\\tfrac{1}{3}\\right)\\sin(x/3) = -\\tfrac{4}{3}\\sin(x/3)", explanation: "Keep the fraction \\(\\tfrac{4}{3}\\) — combining with the chain factor gives a non-integer coefficient." }, { stepNumber: 6, description: "Combine.", workingLatex: "\\tfrac{dy}{dx} = 3\\cos(x/2) - \\tfrac{4}{3}\\sin(x/3)", explanation: "Sum the two contributions." } ], finalAnswer: "\\( 3\\cos(x/2) - \\tfrac{4}{3}\\sin(x/3) \\)" } },
  // ── Evaluate derivatives at specific points ────
  { id: "y2df1-039", topicRef: "y2df1", topicTitle: "Differentiating 39", difficulty: "Standard", answerType: "expression", questionText: "Find the gradient of \\( y = \\sin x \\) at \\( x = \\tfrac{\\pi}{4} \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "gradient"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate.", workingLatex: "\\tfrac{dy}{dx} = \\cos x", explanation: "Standard derivative of \\(\\sin x\\)." }, { stepNumber: 2, description: "Substitute \\(x = \\tfrac{\\pi}{4}\\).", workingLatex: "\\left.\\tfrac{dy}{dx}\\right|_{x=\\pi/4} = \\cos(\\pi/4)", explanation: "Plug the value into the gradient function." }, { stepNumber: 3, description: "Recall the exact value.", workingLatex: "\\cos(\\pi/4) = \\tfrac{\\sqrt{2}}{2}", explanation: "Equivalent to \\(\\tfrac{1}{\\sqrt{2}}\\); the rationalised form is preferred in A-Level marking." } ], finalAnswer: "\\( \\tfrac{\\sqrt{2}}{2} \\)" } },
  { id: "y2df1-040", topicRef: "y2df1", topicTitle: "Differentiating 40", difficulty: "Standard", answerType: "expression", questionText: "Find the gradient of \\( y = \\cos x \\) at \\( x = \\tfrac{\\pi}{3} \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "gradient"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate.", workingLatex: "\\tfrac{dy}{dx} = -\\sin x", explanation: "Standard derivative of \\(\\cos x\\), with the essential minus sign." }, { stepNumber: 2, description: "Substitute \\(x = \\tfrac{\\pi}{3}\\).", workingLatex: "\\left.\\tfrac{dy}{dx}\\right|_{x=\\pi/3} = -\\sin(\\pi/3)", explanation: "Substitute into the gradient function." }, { stepNumber: 3, description: "Recall the exact value.", workingLatex: "\\sin(\\pi/3) = \\tfrac{\\sqrt{3}}{2}", explanation: "A standard exact value from the 30-60-90 triangle." }, { stepNumber: 4, description: "Apply the minus sign.", workingLatex: "\\left.\\tfrac{dy}{dx}\\right|_{x=\\pi/3} = -\\tfrac{\\sqrt{3}}{2}", explanation: "Don't drop the negative — this is a typical mark loss." } ], finalAnswer: "\\( -\\tfrac{\\sqrt{3}}{2} \\)" } },
  { id: "y2df1-041", topicRef: "y2df1", topicTitle: "Differentiating 41", difficulty: "Standard", answerType: "expression", questionText: "Find the gradient of \\( y = 2\\sin x + 3\\cos x \\) at \\( x = \\tfrac{\\pi}{6} \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["trig", "gradient"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate by linearity.", workingLatex: "\\tfrac{dy}{dx} = 2\\cos x - 3\\sin x", explanation: "Standard linear-combination derivative; mind the sign on the \\(\\sin\\) term." }, { stepNumber: 2, description: "Substitute \\(x = \\tfrac{\\pi}{6}\\).", workingLatex: "\\left.\\tfrac{dy}{dx}\\right|_{x=\\pi/6} = 2\\cos(\\pi/6) - 3\\sin(\\pi/6)", explanation: "Plug the value into the gradient function." }, { stepNumber: 3, description: "Recall the exact values.", workingLatex: "\\cos(\\pi/6) = \\tfrac{\\sqrt{3}}{2},\\;\\; \\sin(\\pi/6) = \\tfrac{1}{2}", explanation: "Both come straight from the 30-60-90 triangle." }, { stepNumber: 4, description: "Evaluate.", workingLatex: "2 \\cdot \\tfrac{\\sqrt{3}}{2} - 3 \\cdot \\tfrac{1}{2} = \\sqrt{3} - \\tfrac{3}{2}", explanation: "Multiply each term and combine. Leaving the answer in this exact form is preferred over a decimal." } ], finalAnswer: "\\( \\sqrt{3} - \\tfrac{3}{2} \\)" } },
  { id: "y2df1-042", topicRef: "y2df1", topicTitle: "Differentiating 42", difficulty: "Standard", answerType: "expression", questionText: "Find the gradient of \\( y = \\sin 2x \\) at \\( x = \\tfrac{\\pi}{4} \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate using the linear-argument rule.", workingLatex: "\\tfrac{dy}{dx} = 2\\cos 2x", explanation: "Inner derivative \\(2\\) attaches to \\(\\cos 2x\\)." }, { stepNumber: 2, description: "Substitute \\(x = \\tfrac{\\pi}{4}\\).", workingLatex: "\\left.\\tfrac{dy}{dx}\\right|_{x=\\pi/4} = 2\\cos\\!\\left(2 \\cdot \\tfrac{\\pi}{4}\\right)", explanation: "Plug the value into the gradient function." }, { stepNumber: 3, description: "Simplify the argument.", workingLatex: "= 2\\cos(\\pi/2)", explanation: "\\(2 \\cdot \\tfrac{\\pi}{4} = \\tfrac{\\pi}{2}\\)." }, { stepNumber: 4, description: "Evaluate.", workingLatex: "\\cos(\\pi/2) = 0 \\;\\Rightarrow\\; \\tfrac{dy}{dx} = 0", explanation: "At \\(x = \\tfrac{\\pi}{4}\\), the curve \\(\\sin 2x\\) reaches its maximum, so the tangent is horizontal." } ], finalAnswer: "\\( 0 \\)" } },
  { id: "y2df1-043", topicRef: "y2df1", topicTitle: "Differentiating 43", difficulty: "Standard", answerType: "expression", questionText: "Find the gradient of \\( y = \\cos 3x \\) at \\( x = \\tfrac{\\pi}{6} \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate using the linear-argument rule.", workingLatex: "\\tfrac{dy}{dx} = -3\\sin 3x", explanation: "Multiply by the inner derivative \\(3\\); \\(\\cos\\) contributes a minus." }, { stepNumber: 2, description: "Substitute \\(x = \\tfrac{\\pi}{6}\\).", workingLatex: "\\left.\\tfrac{dy}{dx}\\right|_{x=\\pi/6} = -3\\sin\\!\\left(3 \\cdot \\tfrac{\\pi}{6}\\right)", explanation: "Plug the value into the gradient function." }, { stepNumber: 3, description: "Simplify the argument.", workingLatex: "= -3\\sin(\\pi/2)", explanation: "\\(3 \\cdot \\tfrac{\\pi}{6} = \\tfrac{\\pi}{2}\\)." }, { stepNumber: 4, description: "Evaluate.", workingLatex: "\\sin(\\pi/2) = 1 \\;\\Rightarrow\\; \\tfrac{dy}{dx} = -3", explanation: "The negative coefficient is preserved." } ], finalAnswer: "\\( -3 \\)" } },
  { id: "y2df1-044", topicRef: "y2df1", topicTitle: "Differentiating 44", difficulty: "Foundation", answerType: "expression", questionText: "Find the gradient of \\( y = \\sin x + 2\\cos x \\) at \\( x = 0 \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate by linearity.", workingLatex: "\\tfrac{dy}{dx} = \\cos x - 2\\sin x", explanation: "\\(\\cos x\\) for \\(\\sin x\\)'s derivative; \\(-2\\sin x\\) for \\(2\\cos x\\)'s derivative." }, { stepNumber: 2, description: "Substitute \\(x = 0\\).", workingLatex: "\\left.\\tfrac{dy}{dx}\\right|_{x=0} = \\cos 0 - 2\\sin 0", explanation: "Both trig values at \\(0\\) are easy: \\(\\cos 0 = 1\\), \\(\\sin 0 = 0\\)." }, { stepNumber: 3, description: "Evaluate.", workingLatex: "1 - 0 = 1", explanation: "The \\(\\sin\\) term vanishes at the origin, leaving just the \\(\\cos\\) contribution." } ], finalAnswer: "\\( 1 \\)" } },
  // ── Second derivatives ────
  { id: "y2df1-045", topicRef: "y2df1", topicTitle: "Differentiating 45", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\tfrac{d^2y}{dx^2} \\) when \\( y = \\sin x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "second derivative"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate once to get the first derivative.", workingLatex: "\\tfrac{dy}{dx} = \\cos x", explanation: "Standard derivative of \\(\\sin x\\)." }, { stepNumber: 2, description: "Differentiate again.", workingLatex: "\\tfrac{d^2y}{dx^2} = \\tfrac{d}{dx}(\\cos x)", explanation: "Apply the derivative operator to the first-derivative result." }, { stepNumber: 3, description: "Apply the standard derivative of \\(\\cos x\\).", workingLatex: "\\tfrac{d^2y}{dx^2} = -\\sin x", explanation: "Two derivatives produce a sign flip; after four the cycle returns to \\(\\sin x\\). \\(\\sin x\\) satisfies \\(y'' = -y\\)." } ], finalAnswer: "\\( -\\sin x \\)" } },
  { id: "y2df1-046", topicRef: "y2df1", topicTitle: "Differentiating 46", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\tfrac{d^2y}{dx^2} \\) when \\( y = \\cos x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig", "second derivative"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate once.", workingLatex: "\\tfrac{dy}{dx} = -\\sin x", explanation: "First derivative of \\(\\cos x\\), carrying the standard minus sign." }, { stepNumber: 2, description: "Differentiate again.", workingLatex: "\\tfrac{d^2y}{dx^2} = \\tfrac{d}{dx}(-\\sin x)", explanation: "Apply the derivative to the first-derivative expression." }, { stepNumber: 3, description: "Apply the standard derivative of \\(\\sin x\\).", workingLatex: "\\tfrac{d^2y}{dx^2} = -\\cos x", explanation: "The two minus signs compound to give \\(-\\cos x\\). Both \\(\\sin\\) and \\(\\cos\\) satisfy \\(y'' = -y\\)." } ], finalAnswer: "\\( -\\cos x \\)" } },
  { id: "y2df1-047", topicRef: "y2df1", topicTitle: "Differentiating 47", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\tfrac{d^2y}{dx^2} \\) when \\( y = 3\\sin x + 2\\cos x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate once.", workingLatex: "\\tfrac{dy}{dx} = 3\\cos x - 2\\sin x", explanation: "Linear combination differentiates term by term." }, { stepNumber: 2, description: "Differentiate again.", workingLatex: "\\tfrac{d^2y}{dx^2} = -3\\sin x - 2\\cos x", explanation: "\\(\\cos\\) becomes \\(-\\sin\\) and \\(-\\sin\\) becomes \\(-\\cos\\)." }, { stepNumber: 3, description: "Observe the relationship.", workingLatex: "\\tfrac{d^2y}{dx^2} = -(3\\sin x + 2\\cos x) = -y", explanation: "This confirms the simple-harmonic relation \\(y'' = -y\\) for sine/cosine combinations." } ], finalAnswer: "\\( -3\\sin x - 2\\cos x \\)" } },
  { id: "y2df1-048", topicRef: "y2df1", topicTitle: "Differentiating 48", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\tfrac{d^2y}{dx^2} \\) when \\( y = \\sin 2x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate once.", workingLatex: "\\tfrac{dy}{dx} = 2\\cos 2x", explanation: "Linear-argument rule with \\(k = 2\\) — the chain rule brings down a factor of \\(2\\)." }, { stepNumber: 2, description: "Differentiate the first derivative.", workingLatex: "\\tfrac{d^2y}{dx^2} = 2 \\cdot \\tfrac{d}{dx}(\\cos 2x)", explanation: "The outer \\(2\\) carries through; we now differentiate \\(\\cos 2x\\)." }, { stepNumber: 3, description: "Apply the rule to \\(\\cos 2x\\).", workingLatex: "\\tfrac{d^2y}{dx^2} = 2(-2\\sin 2x) = -4\\sin 2x", explanation: "Each differentiation brings down another factor of \\(k = 2\\), so the second derivative carries \\(k^2 = 4\\)." } ], finalAnswer: "\\( -4\\sin 2x \\)" } },
  { id: "y2df1-049", topicRef: "y2df1", topicTitle: "Differentiating 49", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\tfrac{d^2y}{dx^2} \\) when \\( y = \\cos 3x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate once.", workingLatex: "\\tfrac{dy}{dx} = -3\\sin 3x", explanation: "Linear-argument rule with \\(k = 3\\), and \\(\\cos\\) gives a minus." }, { stepNumber: 2, description: "Differentiate the first derivative.", workingLatex: "\\tfrac{d^2y}{dx^2} = -3 \\cdot \\tfrac{d}{dx}(\\sin 3x)", explanation: "The outer \\(-3\\) carries through; we differentiate \\(\\sin 3x\\) next." }, { stepNumber: 3, description: "Apply the rule to \\(\\sin 3x\\).", workingLatex: "\\tfrac{d^2y}{dx^2} = -3(3\\cos 3x) = -9\\cos 3x", explanation: "Another factor of \\(k = 3\\) compounds to give \\(k^2 = 9\\); the overall sign stays negative." } ], finalAnswer: "\\( -9\\cos 3x \\)" } },
  { id: "y2df1-050", topicRef: "y2df1", topicTitle: "Differentiating 50", difficulty: "Challenge", answerType: "expression", questionText: "Show that \\( y = \\sin(kx) \\) satisfies \\( \\tfrac{d^2y}{dx^2} + k^2 y = 0 \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["trig", "proof"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate once.", workingLatex: "\\tfrac{dy}{dx} = k\\cos(kx)", explanation: "Linear-argument rule for \\(\\sin\\)." }, { stepNumber: 2, description: "Differentiate again.", workingLatex: "\\tfrac{d^2y}{dx^2} = -k^2\\sin(kx)", explanation: "A second factor of \\(k\\) and the minus from differentiating \\(\\cos\\) combine to \\(-k^2\\sin(kx)\\)." }, { stepNumber: 3, description: "Substitute into the equation.", workingLatex: "\\tfrac{d^2y}{dx^2} + k^2 y = -k^2\\sin(kx) + k^2\\sin(kx)", explanation: "Use \\(y = \\sin(kx)\\) to express the \\(k^2 y\\) term." }, { stepNumber: 4, description: "Conclude.", workingLatex: "= 0", explanation: "The two terms cancel exactly, proving the ODE \\(y'' + k^2 y = 0\\) is satisfied." } ], finalAnswer: "\\( y'' + k^2 y = -k^2\\sin kx + k^2\\sin kx = 0 \\). \\(\\blacksquare\\)" } },
  // ── Tangents and stationary points ────
  { id: "y2df1-051", topicRef: "y2df1", topicTitle: "Differentiating 51", difficulty: "Standard", answerType: "expression", questionText: "Find the equation of the tangent to \\( y = \\sin x \\) at the origin.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["trig", "tangent"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate to get the gradient function.", workingLatex: "\\tfrac{dy}{dx} = \\cos x", explanation: "Standard derivative of \\(\\sin x\\)." }, { stepNumber: 2, description: "Evaluate the gradient at \\(x = 0\\).", workingLatex: "m = \\cos 0 = 1", explanation: "This is the slope of the tangent line." }, { stepNumber: 3, description: "Confirm the y-coordinate.", workingLatex: "y(0) = \\sin 0 = 0", explanation: "The tangent passes through the origin \\((0, 0)\\)." }, { stepNumber: 4, description: "Apply the point-slope form.", workingLatex: "y - 0 = 1(x - 0) \\;\\Rightarrow\\; y = x", explanation: "Substituting the gradient and point gives the simplest possible tangent equation." } ], finalAnswer: "\\( y = x \\)" } },
  { id: "y2df1-052", topicRef: "y2df1", topicTitle: "Differentiating 52", difficulty: "Standard", answerType: "expression", questionText: "Find the equation of the tangent to \\( y = \\cos x \\) at \\( x = \\tfrac{\\pi}{2} \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["trig", "tangent"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate.", workingLatex: "\\tfrac{dy}{dx} = -\\sin x", explanation: "Standard derivative of \\(\\cos x\\)." }, { stepNumber: 2, description: "Evaluate the gradient at \\(x = \\tfrac{\\pi}{2}\\).", workingLatex: "m = -\\sin(\\pi/2) = -1", explanation: "\\(\\sin(\\pi/2) = 1\\), and the minus sign carries through." }, { stepNumber: 3, description: "Find the y-coordinate.", workingLatex: "y(\\pi/2) = \\cos(\\pi/2) = 0", explanation: "The tangent passes through \\((\\tfrac{\\pi}{2}, 0)\\)." }, { stepNumber: 4, description: "Apply the point-slope form.", workingLatex: "y - 0 = -1(x - \\pi/2)", explanation: "Substitute \\(m\\) and the point into \\(y - y_0 = m(x - x_0)\\)." }, { stepNumber: 5, description: "Rearrange.", workingLatex: "y = -x + \\tfrac{\\pi}{2}", explanation: "Distribute the \\(-1\\) and isolate \\(y\\)." } ], finalAnswer: "\\( y = -x + \\tfrac{\\pi}{2} \\)" } },
  { id: "y2df1-053", topicRef: "y2df1", topicTitle: "Differentiating 53", difficulty: "Challenge", answerType: "expression", questionText: "Find the equation of the tangent to \\( y = \\sin x + \\cos x \\) at \\( x = \\tfrac{\\pi}{4} \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["trig", "tangent"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate.", workingLatex: "\\tfrac{dy}{dx} = \\cos x - \\sin x", explanation: "Linear combination of standard derivatives." }, { stepNumber: 2, description: "Evaluate the gradient at \\(x = \\tfrac{\\pi}{4}\\).", workingLatex: "m = \\cos(\\pi/4) - \\sin(\\pi/4) = \\tfrac{\\sqrt{2}}{2} - \\tfrac{\\sqrt{2}}{2} = 0", explanation: "Both exact values are equal, so they cancel — the tangent is horizontal here." }, { stepNumber: 3, description: "Find the y-coordinate.", workingLatex: "y(\\pi/4) = \\sin(\\pi/4) + \\cos(\\pi/4) = \\tfrac{\\sqrt{2}}{2} + \\tfrac{\\sqrt{2}}{2} = \\sqrt{2}", explanation: "The two exact values add to \\(\\sqrt{2}\\); the point is \\((\\tfrac{\\pi}{4}, \\sqrt{2})\\)." }, { stepNumber: 4, description: "Write the tangent equation.", workingLatex: "y - \\sqrt{2} = 0(x - \\pi/4) \\;\\Rightarrow\\; y = \\sqrt{2}", explanation: "Since the gradient is zero, the tangent is the horizontal line through the y-value. This is a stationary point of the curve." } ], finalAnswer: "\\( y = \\sqrt{2} \\)" } },
  { id: "y2df1-054", topicRef: "y2df1", topicTitle: "Differentiating 54", difficulty: "Challenge", answerType: "expression", questionText: "Find the stationary points of \\( y = \\sin x + \\cos x \\) for \\( 0 \\le x < 2\\pi \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["trig", "stationary"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate.", workingLatex: "\\tfrac{dy}{dx} = \\cos x - \\sin x", explanation: "We need the derivative to set up the stationary condition." }, { stepNumber: 2, description: "Set the derivative to zero.", workingLatex: "\\cos x - \\sin x = 0", explanation: "Stationary points occur where the tangent is horizontal." }, { stepNumber: 3, description: "Rearrange to a tangent equation.", workingLatex: "\\sin x = \\cos x \\;\\Rightarrow\\; \\tan x = 1", explanation: "Divide both sides by \\(\\cos x\\); valid since \\(\\cos x = 0\\) wouldn't satisfy the original equation." }, { stepNumber: 4, description: "Solve for \\(x\\) in \\([0, 2\\pi)\\).", workingLatex: "x = \\tfrac{\\pi}{4},\\; \\tfrac{5\\pi}{4}", explanation: "\\(\\tan x = 1\\) has period \\(\\pi\\); the two solutions in the interval are the principal value and its \\(\\pi\\)-shift." }, { stepNumber: 5, description: "Find the corresponding y-values.", workingLatex: "y(\\pi/4) = \\tfrac{\\sqrt{2}}{2} + \\tfrac{\\sqrt{2}}{2} = \\sqrt{2},\\;\\; y(5\\pi/4) = -\\tfrac{\\sqrt{2}}{2} - \\tfrac{\\sqrt{2}}{2} = -\\sqrt{2}", explanation: "Both \\(\\sin\\) and \\(\\cos\\) flip sign between the first quadrant and the third, doubling each contribution." }, { stepNumber: 6, description: "State the stationary points.", workingLatex: "(\\tfrac{\\pi}{4},\\sqrt{2})\\; \\text{max};\\;\\; (\\tfrac{5\\pi}{4}, -\\sqrt{2})\\; \\text{min}", explanation: "By symmetry of \\(\\sin x + \\cos x = \\sqrt{2}\\sin(x + \\pi/4)\\), the first is the maximum and the second is the minimum." } ], finalAnswer: "\\( (\\tfrac{\\pi}{4}, \\sqrt{2}) \\) max; \\( (\\tfrac{5\\pi}{4}, -\\sqrt{2}) \\) min." } },
  { id: "y2df1-055", topicRef: "y2df1", topicTitle: "Differentiating 55", difficulty: "Challenge", answerType: "expression", questionText: "Find the x-coordinates of the stationary points of \\( y = 3\\sin x - 4\\cos x \\) for \\( 0 \\le x < 2\\pi \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["trig", "stationary"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate.", workingLatex: "\\tfrac{dy}{dx} = 3\\cos x + 4\\sin x", explanation: "Term-by-term: \\(\\sin x\\) gives \\(\\cos x\\); \\(-\\cos x\\) gives \\(\\sin x\\)." }, { stepNumber: 2, description: "Set the derivative to zero.", workingLatex: "3\\cos x + 4\\sin x = 0", explanation: "Stationary point condition." }, { stepNumber: 3, description: "Rearrange to a tangent equation.", workingLatex: "4\\sin x = -3\\cos x \\;\\Rightarrow\\; \\tan x = -\\tfrac{3}{4}", explanation: "Divide both sides by \\(\\cos x\\); the negative sign moves \\(3\\cos x\\) across." }, { stepNumber: 4, description: "Locate the solutions in \\([0, 2\\pi)\\).", workingLatex: "\\tan x < 0 \\;\\Rightarrow\\; x \\in Q2,\\; Q4", explanation: "Negative tangent values occur in the second and fourth quadrants." }, { stepNumber: 5, description: "Compute the angles.", workingLatex: "x = \\pi - \\arctan(\\tfrac{3}{4}),\\;\\; x = 2\\pi - \\arctan(\\tfrac{3}{4})", explanation: "Use the principal value \\(\\arctan(\\tfrac{3}{4}) \\approx 0.6435\\) reflected into the correct quadrants." }, { stepNumber: 6, description: "Evaluate numerically.", workingLatex: "x \\approx 2.498,\\;\\; 5.640 \\text{ rad}", explanation: "\\(\\pi - 0.6435 \\approx 2.498\\) and \\(2\\pi - 0.6435 \\approx 5.640\\), to three decimal places." } ], finalAnswer: "\\( x \\approx 2.498,\\; 5.640 \\) rad." } },
  // ── Further mixed ────
  { id: "y2df1-056", topicRef: "y2df1", topicTitle: "Differentiating 56", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = 2\\sin x \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the standard derivative.", workingLatex: "\\tfrac{d}{dx}\\sin x = \\cos x", explanation: "The base rule we need before applying linearity." }, { stepNumber: 2, description: "Pull the constant through.", workingLatex: "\\tfrac{dy}{dx} = 2\\,\\tfrac{d}{dx}(\\sin x)", explanation: "Linearity allows the \\(2\\) to factor out." }, { stepNumber: 3, description: "Substitute.", workingLatex: "\\tfrac{dy}{dx} = 2\\cos x", explanation: "Substitute \\(\\cos x\\) for the derivative of \\(\\sin x\\)." } ], finalAnswer: "\\( 2\\cos x \\)" } },
  { id: "y2df1-057", topicRef: "y2df1", topicTitle: "Differentiating 57", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = \\tfrac{\\sin x}{3} + \\tfrac{\\cos x}{5} \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Rewrite with explicit constants.", workingLatex: "y = \\tfrac{1}{3}\\sin x + \\tfrac{1}{5}\\cos x", explanation: "Show the fractional coefficients out front to make the linearity step transparent." }, { stepNumber: 2, description: "Apply linearity.", workingLatex: "\\tfrac{dy}{dx} = \\tfrac{1}{3}\\cos x + \\tfrac{1}{5}(-\\sin x)", explanation: "Differentiate each term with its constant attached." }, { stepNumber: 3, description: "Tidy.", workingLatex: "\\tfrac{dy}{dx} = \\tfrac{\\cos x}{3} - \\tfrac{\\sin x}{5}", explanation: "Write the fractions in the form the question used." } ], finalAnswer: "\\( \\tfrac{\\cos x}{3} - \\tfrac{\\sin x}{5} \\)" } },
  { id: "y2df1-058", topicRef: "y2df1", topicTitle: "Differentiating 58", difficulty: "Foundation", answerType: "expression", questionText: "Given \\( y = a\\sin x + b\\cos x \\) (\\(a, b\\) constants), find \\( \\tfrac{dy}{dx} \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply linearity with symbolic constants.", workingLatex: "\\tfrac{dy}{dx} = a\\,\\tfrac{d}{dx}(\\sin x) + b\\,\\tfrac{d}{dx}(\\cos x)", explanation: "The constants \\(a\\) and \\(b\\) behave just like any other multipliers." }, { stepNumber: 2, description: "Substitute the standard derivatives.", workingLatex: "\\tfrac{dy}{dx} = a\\cos x + b(-\\sin x)", explanation: "Use the two standard results, keeping brackets to track the sign." }, { stepNumber: 3, description: "Combine.", workingLatex: "\\tfrac{dy}{dx} = a\\cos x - b\\sin x", explanation: "This is the canonical derivative of a sinusoidal combination — worth memorising." } ], finalAnswer: "\\( a\\cos x - b\\sin x \\)" } },
  { id: "y2df1-059", topicRef: "y2df1", topicTitle: "Differentiating 59", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = \\sin x + \\cos 2x \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate term by term.", workingLatex: "\\tfrac{dy}{dx} = \\tfrac{d}{dx}(\\sin x) + \\tfrac{d}{dx}(\\cos 2x)", explanation: "Two different inner functions, so handle each independently." }, { stepNumber: 2, description: "Standard derivative of \\(\\sin x\\).", workingLatex: "\\tfrac{d}{dx}(\\sin x) = \\cos x", explanation: "First term has no chain-rule complication." }, { stepNumber: 3, description: "Linear-argument rule on \\(\\cos 2x\\).", workingLatex: "\\tfrac{d}{dx}(\\cos 2x) = -2\\sin 2x", explanation: "Inner derivative \\(2\\), and \\(\\cos\\)'s derivative contributes the minus." }, { stepNumber: 4, description: "Combine.", workingLatex: "\\tfrac{dy}{dx} = \\cos x - 2\\sin 2x", explanation: "Sum the two contributions." } ], finalAnswer: "\\( \\cos x - 2\\sin 2x \\)" } },
  { id: "y2df1-060", topicRef: "y2df1", topicTitle: "Differentiating 60", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = \\sin 3x + \\cos x \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate term by term.", workingLatex: "\\tfrac{dy}{dx} = \\tfrac{d}{dx}(\\sin 3x) + \\tfrac{d}{dx}(\\cos x)", explanation: "Two trig terms with different inner functions." }, { stepNumber: 2, description: "Linear-argument rule on \\(\\sin 3x\\).", workingLatex: "\\tfrac{d}{dx}(\\sin 3x) = 3\\cos 3x", explanation: "Inner derivative \\(3\\) multiplies the outer \\(\\cos\\)." }, { stepNumber: 3, description: "Standard derivative of \\(\\cos x\\).", workingLatex: "\\tfrac{d}{dx}(\\cos x) = -\\sin x", explanation: "No chain rule needed for the second term." }, { stepNumber: 4, description: "Combine.", workingLatex: "\\tfrac{dy}{dx} = 3\\cos 3x - \\sin x", explanation: "Add the two pieces." } ], finalAnswer: "\\( 3\\cos 3x - \\sin x \\)" } },
  { id: "y2df1-061", topicRef: "y2df1", topicTitle: "Differentiating 61", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = 2\\sin 5x - 7\\cos x \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply linearity.", workingLatex: "\\tfrac{dy}{dx} = 2\\,\\tfrac{d}{dx}(\\sin 5x) - 7\\,\\tfrac{d}{dx}(\\cos x)", explanation: "Handle the two trig terms separately, each with its leading constant." }, { stepNumber: 2, description: "Differentiate \\(\\sin 5x\\).", workingLatex: "2\\,\\tfrac{d}{dx}(\\sin 5x) = 2(5\\cos 5x) = 10\\cos 5x", explanation: "Inner derivative \\(5\\) combines with the outer \\(2\\)." }, { stepNumber: 3, description: "Differentiate \\(\\cos x\\).", workingLatex: "-7\\,\\tfrac{d}{dx}(\\cos x) = -7(-\\sin x) = 7\\sin x", explanation: "Two negatives multiply to a positive." }, { stepNumber: 4, description: "Combine.", workingLatex: "\\tfrac{dy}{dx} = 10\\cos 5x + 7\\sin x", explanation: "Both terms end up positive." } ], finalAnswer: "\\( 10\\cos 5x + 7\\sin x \\)" } },
  { id: "y2df1-062", topicRef: "y2df1", topicTitle: "Differentiating 62", difficulty: "Challenge", answerType: "expression", questionText: "Show that \\( y = \\cos(kx) \\) satisfies \\( \\tfrac{d^2y}{dx^2} + k^2 y = 0 \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["trig", "proof"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate once.", workingLatex: "\\tfrac{dy}{dx} = -k\\sin(kx)", explanation: "Linear-argument rule on \\(\\cos\\)." }, { stepNumber: 2, description: "Differentiate again.", workingLatex: "\\tfrac{d^2y}{dx^2} = -k(k\\cos(kx)) = -k^2\\cos(kx)", explanation: "Each derivative brings down another factor of \\(k\\); the sign chain gives \\(-k^2\\)." }, { stepNumber: 3, description: "Substitute into the ODE.", workingLatex: "\\tfrac{d^2y}{dx^2} + k^2 y = -k^2\\cos(kx) + k^2\\cos(kx)", explanation: "Use \\(y = \\cos(kx)\\) for the second term." }, { stepNumber: 4, description: "Conclude.", workingLatex: "= 0", explanation: "The terms cancel exactly, verifying the simple-harmonic-motion equation." } ], finalAnswer: "\\( y'' + k^2 y = 0 \\). \\(\\blacksquare\\)" } },
  { id: "y2df1-063", topicRef: "y2df1", topicTitle: "Differentiating 63", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = 2\\sin 3x - \\sin x \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply linearity.", workingLatex: "\\tfrac{dy}{dx} = 2\\,\\tfrac{d}{dx}(\\sin 3x) - \\tfrac{d}{dx}(\\sin x)", explanation: "Both terms are sines but with different inner functions." }, { stepNumber: 2, description: "Differentiate \\(\\sin 3x\\).", workingLatex: "2\\,\\tfrac{d}{dx}(\\sin 3x) = 2(3\\cos 3x) = 6\\cos 3x", explanation: "Inner derivative \\(3\\) combines with the outer \\(2\\)." }, { stepNumber: 3, description: "Differentiate \\(\\sin x\\).", workingLatex: "\\tfrac{d}{dx}(\\sin x) = \\cos x", explanation: "Plain standard derivative." }, { stepNumber: 4, description: "Combine.", workingLatex: "\\tfrac{dy}{dx} = 6\\cos 3x - \\cos x", explanation: "The minus is preserved from the original expression." } ], finalAnswer: "\\( 6\\cos 3x - \\cos x \\)" } },
  { id: "y2df1-064", topicRef: "y2df1", topicTitle: "Differentiating 64", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = \\cos 4x - \\cos x \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply linearity.", workingLatex: "\\tfrac{dy}{dx} = \\tfrac{d}{dx}(\\cos 4x) - \\tfrac{d}{dx}(\\cos x)", explanation: "Differentiate each cosine separately." }, { stepNumber: 2, description: "Differentiate \\(\\cos 4x\\).", workingLatex: "\\tfrac{d}{dx}(\\cos 4x) = -4\\sin 4x", explanation: "Linear-argument rule with \\(k = 4\\)." }, { stepNumber: 3, description: "Differentiate \\(\\cos x\\).", workingLatex: "\\tfrac{d}{dx}(\\cos x) = -\\sin x", explanation: "Standard result." }, { stepNumber: 4, description: "Combine, watching the outer minus.", workingLatex: "\\tfrac{dy}{dx} = -4\\sin 4x - (-\\sin x) = -4\\sin 4x + \\sin x", explanation: "The outer subtraction flips the second term's sign — a classic sign-error trap." }, { stepNumber: 5, description: "Reorder.", workingLatex: "\\tfrac{dy}{dx} = \\sin x - 4\\sin 4x", explanation: "Equivalent form; either order is acceptable." } ], finalAnswer: "\\( \\sin x - 4\\sin 4x \\)" } },
  { id: "y2df1-065", topicRef: "y2df1", topicTitle: "Differentiating 65", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\tfrac{d^2y}{dx^2} \\) when \\( y = 2\\sin 3x \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(\\sin 3x\\).", workingLatex: "\\tfrac{d}{dx}(\\sin 3x) = 3\\cos 3x", explanation: "Linear-argument rule with \\(k = 3\\)." }, { stepNumber: 2, description: "Multiply through by the outer constant.", workingLatex: "\\tfrac{dy}{dx} = 2(3\\cos 3x) = 6\\cos 3x", explanation: "Combine the outer \\(2\\) with the chain factor." }, { stepNumber: 3, description: "Differentiate again.", workingLatex: "\\tfrac{d^2y}{dx^2} = 6(-3\\sin 3x) = -18\\sin 3x", explanation: "Another factor of \\(3\\) from the inner derivative; \\(\\cos\\)'s derivative contributes the minus." } ], finalAnswer: "\\( -18\\sin 3x \\)" } },
  { id: "y2df1-066", topicRef: "y2df1", topicTitle: "Differentiating 66", difficulty: "Standard", answerType: "expression", questionText: "Differentiate \\( y = 5\\sin x + 3\\cos 2x - x \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply linearity to each term.", workingLatex: "\\tfrac{dy}{dx} = 5\\,\\tfrac{d}{dx}(\\sin x) + 3\\,\\tfrac{d}{dx}(\\cos 2x) - \\tfrac{d}{dx}(x)", explanation: "Three independent terms differentiate separately." }, { stepNumber: 2, description: "Differentiate the \\(\\sin x\\) term.", workingLatex: "5\\,\\tfrac{d}{dx}(\\sin x) = 5\\cos x", explanation: "Standard derivative with the outer constant." }, { stepNumber: 3, description: "Differentiate \\(\\cos 2x\\).", workingLatex: "3\\,\\tfrac{d}{dx}(\\cos 2x) = 3(-2\\sin 2x) = -6\\sin 2x", explanation: "Inner derivative \\(2\\), outer \\(3\\), and the minus from \\(\\cos\\)'s derivative all combine." }, { stepNumber: 4, description: "Differentiate the linear term.", workingLatex: "\\tfrac{d}{dx}(x) = 1", explanation: "Power rule on \\(x^1\\)." }, { stepNumber: 5, description: "Combine.", workingLatex: "\\tfrac{dy}{dx} = 5\\cos x - 6\\sin 2x - 1", explanation: "Sum the three contributions, carrying the original minus on the linear term." } ], finalAnswer: "\\( 5\\cos x - 6\\sin 2x - 1 \\)" } },
  { id: "y2df1-067", topicRef: "y2df1", topicTitle: "Differentiating 67", difficulty: "Standard", answerType: "expression", questionText: "Find the gradient of \\( y = \\sin 4x \\) at \\( x = \\tfrac{\\pi}{8} \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate.", workingLatex: "\\tfrac{dy}{dx} = 4\\cos 4x", explanation: "Linear-argument rule with \\(k = 4\\)." }, { stepNumber: 2, description: "Substitute \\(x = \\tfrac{\\pi}{8}\\).", workingLatex: "\\left.\\tfrac{dy}{dx}\\right|_{x=\\pi/8} = 4\\cos\\!\\left(4 \\cdot \\tfrac{\\pi}{8}\\right)", explanation: "Plug the value into the gradient function." }, { stepNumber: 3, description: "Simplify the argument.", workingLatex: "= 4\\cos(\\pi/2)", explanation: "\\(4 \\cdot \\tfrac{\\pi}{8} = \\tfrac{\\pi}{2}\\)." }, { stepNumber: 4, description: "Evaluate.", workingLatex: "\\cos(\\pi/2) = 0 \\;\\Rightarrow\\; \\tfrac{dy}{dx} = 0", explanation: "The point is a stationary point of \\(\\sin 4x\\); the gradient is exactly zero." } ], finalAnswer: "\\( 0 \\)" } },
  { id: "y2df1-068", topicRef: "y2df1", topicTitle: "Differentiating 68", difficulty: "Standard", answerType: "expression", questionText: "Find the gradient of \\( y = \\cos 2x \\) at \\( x = \\tfrac{\\pi}{6} \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate.", workingLatex: "\\tfrac{dy}{dx} = -2\\sin 2x", explanation: "Linear-argument rule with \\(k = 2\\) on \\(\\cos\\)." }, { stepNumber: 2, description: "Substitute \\(x = \\tfrac{\\pi}{6}\\).", workingLatex: "\\left.\\tfrac{dy}{dx}\\right|_{x=\\pi/6} = -2\\sin(\\pi/3)", explanation: "Argument: \\(2 \\cdot \\tfrac{\\pi}{6} = \\tfrac{\\pi}{3}\\)." }, { stepNumber: 3, description: "Recall \\(\\sin(\\pi/3)\\).", workingLatex: "\\sin(\\pi/3) = \\tfrac{\\sqrt{3}}{2}", explanation: "Standard exact value." }, { stepNumber: 4, description: "Evaluate.", workingLatex: "-2 \\cdot \\tfrac{\\sqrt{3}}{2} = -\\sqrt{3}", explanation: "The factors of \\(2\\) cancel." } ], finalAnswer: "\\( -\\sqrt{3} \\)" } },
  { id: "y2df1-069", topicRef: "y2df1", topicTitle: "Differentiating 69", difficulty: "Challenge", answerType: "expression", questionText: "Find the equation of the normal to \\( y = \\sin x \\) at \\( x = \\tfrac{\\pi}{2} \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["trig", "normal"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate the curve.", workingLatex: "\\tfrac{dy}{dx} = \\cos x", explanation: "Standard derivative of \\(\\sin x\\)." }, { stepNumber: 2, description: "Evaluate the gradient at \\(x = \\tfrac{\\pi}{2}\\).", workingLatex: "m_T = \\cos(\\pi/2) = 0", explanation: "This is the gradient of the tangent — and it's zero, meaning the tangent is horizontal." }, { stepNumber: 3, description: "Find the y-coordinate.", workingLatex: "y(\\pi/2) = \\sin(\\pi/2) = 1", explanation: "The point of contact is \\((\\tfrac{\\pi}{2}, 1)\\)." }, { stepNumber: 4, description: "Interpret the normal.", workingLatex: "m_N = -\\tfrac{1}{m_T} = -\\tfrac{1}{0}\\; (\\text{undefined})", explanation: "Because the tangent is horizontal, the normal is vertical — its gradient is undefined and the normal cannot be written in the form \\(y = mx + c\\)." }, { stepNumber: 5, description: "Write the vertical normal.", workingLatex: "x = \\tfrac{\\pi}{2}", explanation: "A vertical line through \\((\\tfrac{\\pi}{2}, 1)\\) has equation \\(x = \\tfrac{\\pi}{2}\\)." } ], finalAnswer: "Normal is \\( x = \\tfrac{\\pi}{2} \\)." } },
  { id: "y2df1-070", topicRef: "y2df1", topicTitle: "Differentiating 70", difficulty: "Foundation", answerType: "expression", questionText: "Differentiate \\( y = 6\\sin x \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the standard derivative.", workingLatex: "\\tfrac{d}{dx}\\sin x = \\cos x", explanation: "Standard result for differentiating \\(\\sin x\\)." }, { stepNumber: 2, description: "Pull the constant through.", workingLatex: "\\tfrac{dy}{dx} = 6\\,\\tfrac{d}{dx}(\\sin x)", explanation: "Linearity lets the \\(6\\) sit outside the derivative." }, { stepNumber: 3, description: "Substitute.", workingLatex: "\\tfrac{dy}{dx} = 6\\cos x", explanation: "Substitute \\(\\cos x\\) for the derivative of \\(\\sin x\\)." } ], finalAnswer: "\\( 6\\cos x \\)" } },
  { id: "y2df1-071", topicRef: "y2df1", topicTitle: "Differentiating 71", difficulty: "Challenge", answerType: "expression", questionText: "Given \\( y = a\\sin(kx) + b\\cos(kx) \\), find \\( \\tfrac{dy}{dx} \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["trig", "general"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply linearity with symbolic constants.", workingLatex: "\\tfrac{dy}{dx} = a\\,\\tfrac{d}{dx}\\sin(kx) + b\\,\\tfrac{d}{dx}\\cos(kx)", explanation: "Constants \\(a\\), \\(b\\), and \\(k\\) all behave like fixed numbers." }, { stepNumber: 2, description: "Use the linear-argument rule on each term.", workingLatex: "\\tfrac{d}{dx}\\sin(kx) = k\\cos(kx),\\;\\; \\tfrac{d}{dx}\\cos(kx) = -k\\sin(kx)", explanation: "The inner derivative \\(k\\) multiplies each outer derivative; the minus appears on the \\(\\cos\\) result." }, { stepNumber: 3, description: "Substitute.", workingLatex: "\\tfrac{dy}{dx} = ak\\cos(kx) + b(-k\\sin(kx)) = ak\\cos(kx) - bk\\sin(kx)", explanation: "Combine the constants and the chain-rule factors carefully." }, { stepNumber: 4, description: "Factor out \\(k\\).", workingLatex: "\\tfrac{dy}{dx} = k\\bigl(a\\cos(kx) - b\\sin(kx)\\bigr)", explanation: "All terms share a factor of \\(k\\); the bracketed expression is the natural derivative of the original sinusoidal combination." } ], finalAnswer: "\\( k\\bigl(a\\cos(kx) - b\\sin(kx)\\bigr) \\)" } },
];
